def transform(g):
    n=len(g); m=n//2; N=n*n
    out=[[0]*N for _ in range(N)]
    for I in range(n):
        for J in range(n):
            for p in range(n):
                for q in range(n):
                    pf=(n-1-p) if I!=m else p
                    qf=(n-1-q) if J!=m else q
                    out[n*I+p][n*J+q]=g[pf][qf]
    return out
